PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber
       (AVG(?claimLoss) AS ?averageLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:against ?pcd .

    ?pcd in:hasPolicy ?policy .
    ?policy in:policyNumber ?policyNumber .

    OPTIONAL {
      SELECT ?claim (SUM(?v) AS ?lossPaymentSum)
      WHERE {
        ?claim in:hasLossPayment ?lp .
        ?lp in:lossPaymentAmount ?v .
      }
      GROUP BY ?claim
    }

    OPTIONAL {
      SELECT ?claim (SUM(?v) AS ?lossReserveSum)
      WHERE {
        ?claim in:hasLossReserve ?lr .
        ?lr in:lossReserveAmount ?v .
      }
      GROUP BY ?claim
    }

    OPTIONAL {
      SELECT ?claim (SUM(?v) AS ?expensePaymentSum)
      WHERE {
        ?claim in:hasExpensePayment ?ep .
        ?ep in:expensePaymentAmount ?v .
      }
      GROUP BY ?claim
    }

    OPTIONAL {
      SELECT ?claim (SUM(?v) AS ?expenseReserveSum)
      WHERE {
        ?claim in:hasExpenseReserve ?er .
        ?er in:expenseReserveAmount ?v .
      }
      GROUP BY ?claim
    }

    BIND(
      COALESCE(?lossPaymentSum, 0) +
      COALESCE(?lossReserveSum, 0) +
      COALESCE(?expensePaymentSum, 0) +
      COALESCE(?expenseReserveSum, 0)
      AS ?claimLoss
    )
  }
}
GROUP BY ?policyNumber
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?premiumAmount
WHERE {
  SERVICE <mapped> {
    ?policyCoverageDetail in:hasPolicy ?policy ;
                          in:hasPremiumAmount ?premium .
    ?policy in:policyNumber ?policyNumber .
    ?premium in:premiumAmount ?premiumAmount .
  }
}
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyNumber ?coverageEffectiveDate ?coverageExpirationDate ?premiumAmount
WHERE {
  SERVICE <mapped> {
    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy ;
              in:hasPremiumAmount ?premium ;
              in:policyCoverageEffectiveDate ?coverageEffectiveDate ;
              in:policyCoverageExpirationDate ?coverageExpirationDate .

    ?policy in:policyNumber ?policyNumber .
    ?premium in:premiumAmount ?premiumAmount .
  }
}
ORDER BY ?policyNumber ?coverageEffectiveDate ?coverageExpirationDate

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyHolder ?claim ?catastrophe
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:against ?coverage ;
           in:hasCatastrophe ?catastrophe .

    ?coverage a in:PolicyCoverageDetail ;
              in:hasPolicy ?policy .

    ?policy a in:Policy ;
            in:hasPolicyHolder ?policyHolder .
  }
}

PREFIX in: <http://data.world/schema/insurance/>

SELECT (COUNT(DISTINCT ?policy) AS ?policyCount)
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy .
  }
}
